import express, { Express, Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import cors, { CorsOptions } from 'cors';
import path from 'path';
import dotenv from 'dotenv';
import { createServer } from 'http';
import { Server as SocketIOServer } from 'socket.io';
import db from './config/database';
import postsRoutes from './routes/posts';

// Tải biến môi trường
dotenv.config({ path: path.join(__dirname, '../.env') });
if (!process.env.POSTGRES_DB) {
  dotenv.config({ path: path.join(__dirname, '../../../.env') });
}

// Kiểm tra kết nối cơ sở dữ liệu
const testDbConnection = async () => {
  try {
    await db.init();
    await db.query('SELECT NOW() as current_time');
  } catch (error) {
    console.log('Đang thử kết nối lại cơ sở dữ liệu sau 5 giây...');
    setTimeout(testDbConnection, 5000);
  }
};

// Khởi tạo ứng dụng Express
const app: Express = express();
const httpServer = createServer(app);

// Khởi động máy chủ
const startServer = async () => {
  // Kiểm tra nếu server đã được khởi tạo
  if (httpServer.listening) {
    console.log('🔄 Server đã được khởi động trước đó');
    return;
  }

  try {
    await testDbConnection();
    
    const PORT = Number(process.env.PORT) || 3002;
    const HOST = process.env.HOST || 'localhost';
    
    // Đảm bảo không lắng nghe nhiều lần
    if (!httpServer.listening) {
      httpServer.listen(PORT, HOST, () => {
        console.log(`🟢 Máy chủ đang chạy tại http://${HOST}:${PORT}`);
        console.log(`🌍 Môi trường: ${process.env.NODE_ENV || 'development'}`);
        console.log(`🔗 API: http://${HOST}:${PORT}/api`);
      });
    }
  } catch (error) {
    console.error('❌ Không thể khởi động máy chủ:', error);
    process.exit(1);
  }
};

// Kiểm tra xem có đang chạy trong môi trường test không
if (process.env.NODE_ENV !== 'test') {
  startServer();
}

// Middleware để log tất cả các request
app.use((req: Request, res: Response, next: NextFunction) => {
  console.log(`\n=== ${new Date().toISOString()} ===`);
  console.log(`[${req.method}] ${req.originalUrl}`);
  console.log('Base URL:', req.baseUrl);
  console.log('Path:', req.path);
  console.log('Query:', req.query);
  console.log('Headers:', {
    'content-type': req.get('content-type'),
    'authorization': req.get('authorization') ? '***' : undefined,
    'user-agent': req.get('user-agent')
  });
  next();
});

// Áp dụng các middleware cần thiết
app.use(helmet()); // Bảo mật HTTP headers
app.use(express.json()); // Phân tích JSON request
app.use(express.urlencoded({ extended: true })); // Phân tích URL-encoded data

// Cấu hình CORS (Cross-Origin Resource Sharing)
const corsOptions: CorsOptions = {
  origin: ['http://localhost:3000', 'http://localhost:3001', 'http://localhost:3004'],
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true // Cho phép gửi cookie qua CORS
};

// Áp dụng CORS
app.use(cors(corsOptions));
app.options('*', cors(corsOptions)); // Xử lý preflight requests

// Log CORS headers
app.use((req: Request, res: Response, next: NextFunction) => {
  res.header('Access-Control-Allow-Origin', req.headers.origin || '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Credentials', 'true');
  
  // Log response headers
  console.log('Response Headers:', {
    'Access-Control-Allow-Origin': res.getHeader('Access-Control-Allow-Origin'),
    'Access-Control-Allow-Methods': res.getHeader('Access-Control-Allow-Methods'),
    'Access-Control-Allow-Headers': res.getHeader('Access-Control-Allow-Headers'),
    'Access-Control-Allow-Credentials': res.getHeader('Access-Control-Allow-Credentials')
  });
  
  next();
});

// Giới hạn tỷ lệ request
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 phút
  max: 100 // Giới hạn mỗi IP 100 request mỗi cửa sổ thời gian
});
app.use(limiter);

// Endpoint kiểm tra trạng thái
app.get('/api/health', (req: Request, res: Response) => {
  res.status(200).json({ 
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Đăng ký routes với cả hai định dạng URL
app.use('/api', postsRoutes);  // Cho các request từ API Gateway
app.use('', postsRoutes);      // Cho các request trực tiếp không có tiền tố

// Route kiểm thử
app.get(['/api/test', '/test'], (req: Request, res: Response) => {
  res.json({ 
    success: true,
    message: 'Kết nối API thành công!',
    timestamp: new Date().toISOString()
  });
});

// Xử lý lỗi 404 - Không tìm thấy
app.use('/api/*', (req: Request, res: Response) => {
  console.error(`❌ 404 - Không tìm thấy: ${req.method} ${req.originalUrl}`);
  res.status(404).json({
    success: false,
    message: 'Không tìm thấy tài nguyên',
    error: {
      code: 404,
      description: `Không tìm thấy ${req.originalUrl} trên máy chủ này`,
      method: req.method,
      path: req.path,
      query: req.query
    },
    timestamp: new Date().toISOString()
  });
});

// Xử lý lỗi tổng thể
app.use((err: any, req: Request, res: Response, next: NextFunction) => {
  console.error('❌ Lỗi:', err);
  res.status(err.status || 500).json({ 
    status: 'error', 
    message: err.message || 'Lỗi máy chủ nội bộ',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Start server
startServer();

// Handle unhandled rejections
process.on('unhandledRejection', (reason: unknown) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error: Error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});
